import {usePluginStore,useWatchEvent} from '@/hooks/plugin';import {CalendarFlipRenderer,CalendarFlipState,calendarValues,loadCalendarFlipFont} from '@/calendar-flip';
export default function(name:string){const plugin=usePluginStore(),ActionID=window.argv[3].plugin.uuid+'.'+name,items=new Map<string,any>();function stop(context:string){plugin.Unterval(ActionID+context);items.delete(context);}async function start(context:string){stop(context);const st={renderer:new CalendarFlipRenderer(),clock:new CalendarFlipState(),ready:false,busy:false,last:''};items.set(context,st);try{await loadCalendarFlipFont();if(items.get(context)!==st)return;st.ready=true;draw(context,true);plugin.Interval(ActionID+context,33,()=>draw(context));}catch(e){console.error(JSON.stringify({event:'calendar_flip_font_error',error:String(e)}));}}function draw(context:string,force=false){const st=items.get(context),a=plugin.getAction(context);if(!st?.ready||!a||st.busy)return;const s=a.settings as any,now=performance.now();st.clock.update(calendarValues(new Date(),s.hour12===true),now);const p=st.clock.progress(now,s),key=JSON.stringify(s)+st.clock.revision+':'+p;if(!force&&st.last===key)return;const canvas=st.renderer.draw(st.clock.from,st.clock.to,p,s);if(s.transport==='binary'){st.busy=true;canvas.toBlob(async blob=>{try{if(blob&&items.get(context)===st){a.setImageBlob(await blob.arrayBuffer(),'image/png');st.last=key;}}finally{st.busy=false;}},'image/png');}else try{a.setImage(canvas.toDataURL('image/jpeg',.94));st.last=key;}catch(e){console.error(JSON.stringify({event:'calendar_flip_send_error',error:String(e)}));}}useWatchEvent('action',{ActionID,willAppear:({context})=>start(context),willDisappear:({context})=>stop(context),didReceiveSettings:({context})=>draw(context,true)});}
